159	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
160	        HttpHeaders headers = new HttpHeaders();
161	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
162	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
163	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
