180	        }
181	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
182	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
183	        }
184	        Owner householdDuplicate = this.clinicService.findHouseholdDuplicateOf(owner);
