268	        if (currentOwner != null) {
269	            Pet currentPet = this.clinicService.findPetById(petId);
270	            if (currentPet != null) {
271	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
272	                currentPet.setName(petFieldsDto.getName());
273	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
274	                this.clinicService.savePet(currentPet);
275	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
